import type { postSummarySchema } from "@dasa122/contract";
import { Button, buttonClassName, Meta, SourceBadge, Tag } from "@dasa122/ui";
import { Link } from "@tanstack/react-router";
import { formatDate } from "../utils/format";

export type AdminPost = ReturnType<typeof postSummarySchema.parse>;

/**
 * One post in the admin list. It is the same row vocabulary as the public feed
 * with the moderation facts added: status, a delete action, and an edit link.
 *
 * A GitHub post is generated by the sync worker, so it has no body and no draft
 * state. It renders a `Generated` marker instead of an edit link.
 */
export function AdminPostRow({
  post,
  onDelete,
}: {
  post: AdminPost;
  onDelete: () => void;
}) {
  const generated = post.source === "github";
  const status = post.status === "published" ? "Published" : "Draft";
  const date = formatDate(post.publishedAt ?? post.createdAt);
  const meta = [status, date].filter(Boolean).join(" · ");

  return (
    <article className="flex flex-wrap items-baseline gap-x-8 gap-y-2 py-5">
      <div className="w-20 shrink-0">
        <SourceBadge source={post.source} />
      </div>

      <div className="min-w-0 flex-1">
        <h3 className="text-xl leading-snug tracking-[-0.01em] md:text-2xl">
          {post.title}
        </h3>
        {post.tags.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-1.5">
            {post.tags.map((tag) => (
              <Tag key={tag}>{tag}</Tag>
            ))}
          </div>
        )}
      </div>

      <Meta>{meta}</Meta>

      <div className="flex items-baseline gap-x-5">
        {generated ? (
          <Meta>Generated</Meta>
        ) : (
          <Link
            className={buttonClassName("quiet")}
            params={{ id: post.id }}
            to="/admin/news/$id"
          >
            Edit
          </Link>
        )}
        <Button onClick={onDelete} variant="quiet">
          Delete
        </Button>
      </div>
    </article>
  );
}
